import React, {useState} from 'react';
import './App.css';
import {Main} from "./Main";
import {Start} from "./Start";


function App() {
  const [videoPlayed, setVideoPlayed] = useState(false);

  const handlePlayVid = () => {
      setVideoPlayed(true); // Update state when video is played
  };

  return (
    <Start onPlayVid={handlePlayVid} />
  );
}

export default App;
